SELECT SUM(AMOUNT) AS "ORG_CONTRACTED_AMOUNT" FROM (SELECT "CONTRACT_NUMBER" AS CONTRACT_NUMBER, "CONTRACT_ITEM" AS CONTRACT_ITEM, "ORGANIZATION_NAME" AS ORGANIZATION_NAME, "CURRENCY" AS CURRENCY, (CAST("AMOUNT" AS DECIMAL(38, 9))) AS AMOUNT, CAST("START_DATE" AS DATE) AS CONTRACT_START_DAY, CAST("END_DATE" AS DATE) AS CONTRACT_END_DAY, (DATEDIFF(DAY, CAST("START_DATE" AS DATE), CAST("END_DATE" AS DATE))) AS CONTRACT_TERM_DAYS FROM contract_items) AS base ORDER BY "ORG_CONTRACTED_AMOUNT" DESC NULLS LAST LIMIT 100
